contracts/strategies/base/aerodrome/Stra.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import "../../../common/StratManagerUpgradeable.sol";
import "../../../common/interfaces/IERC20Extended.sol";
import "../../../common/DynamicFeeManager.sol";
import "./interfaces/ISolidlyRouter.sol";
import "./interfaces/IVelodromeGauge.sol";
import "./interfaces/ISolidlyPair.sol";

contract StrategyAerodromeGauge is StratManagerUpgradeable, DynamicFeeManager {
    using SafeERC20Upgradeable for IERC20Upgradeable;

    // Tokens used
    address public native;
    address public output;
    address public want;
    address public lpToken0;
    address public lpToken1;

    // Third party contracts
    address public gauge;
    address public factory;

    uint256 public feeOnProfits;

    bool public stable;
    bool public harvestOnDeposit;
    uint256 public lastHarvest;

    ISolidlyRouter.Route[] public outputToNativeRoute;
    ISolidlyRouter.Route[] public outputToLp0Route;
    ISolidlyRouter.Route[] public outputToLp1Route;

    event StratHarvest(address indexed harvester, uint256 wantHarvested, uint256 tvl);
    event Deposit(uint256 tvl);
    event Withdraw(uint256 tvl);
    event ChargedFees(uint256 callFees, uint256 feeAmount1, uint256 feeAmount2, uint256 strategistFees);

    function initialize(
        address _want,
        address _gauge,
        address[] calldata _addresses,
        ISolidlyRouter.Route[] calldata _outputToNativeRoute,
        ISolidlyRouter.Route[] calldata _outputToLp0Route,
        ISolidlyRouter.Route[] calldata _outputToLp1Route
    ) external initializer {
        __StratManager_init(_addresses[0], _addresses[1], _addresses[2], _addresses[3], _addresses[4]);
        __DynamicFeeManager_init();

        want = _want;
        gauge = _gauge;

        feeOnProfits = 35; // 3.5%

        factory = ISolidlyRouter(dystRouter).defaultFactory();
        stable = ISolidlyPair(want).stable();

        for (uint i; i < _outputToNativeRoute.length; ++i) {
            outputToNativeRoute.push(_outputToNativeRoute[i]);
        }

        for (uint i; i < _outputToLp0Route.length; ++i) {
            outputToLp0Route.push(_outputToLp0Route[i]);
        }

        for (uint i; i < _outputToLp1Route.length; ++i) {
            outputToLp1Route.push(_outputToLp1Route[i]);
        }

        output = outputToNativeRoute[0].from;
        native = outputToNativeRoute[outputToNativeRoute.length - 1].to;
        lpToken0 = ISolidlyPair(want).token0();
        lpToken1 = ISolidlyPair(want).token1();

        _giveAllowances();
    }

    // puts the funds to work
    function deposit() public whenNotPaused {
        uint256 wantBal = IERC20Upgradeable(want).balanceOf(address(this));

        if (wantBal > 0) {
            IVelodromeGauge(gauge).deposit(wantBal, address(this));
            emit Deposit(balanceOf());
        }
    }

    function withdraw(uint256 _amount) external {
        require(msg.sender == vault, "!vault");

        uint256 wantBal = IERC20Upgradeable(want).balanceOf(address(this));

        if (wantBal < _amount) {
            IVelodromeGauge(gauge).withdraw(_amount - wantBal);
            wantBal = IERC20Upgradeable(want).balanceOf(address(this));
        }

        if (wantBal > _amount) {
            wantBal = _amount;
        }

        if (tx.origin != owner() && !paused()) {
            uint256 withdrawalFeeAmount = (wantBal * withdrawalFee) / WITHDRAWAL_MAX;
            wantBal = wantBal - withdrawalFeeAmount;
        }

        IERC20Upgradeable(want).safeTransfer(vault, wantBal);

        emit Withdraw(balanceOf());
    }

    function beforeDeposit() external virtual override {
        if (harvestOnDeposit) {
            require(msg.sender == vault, "!vault");
            _harvest(tx.origin);
        }
    }

    function harvest() external virtual {
        _harvest(tx.origin);
    }

    function harvest(address callFeeRecipient) external virtual {
        _harvest(callFeeRecipient);
    }

    // compounds earnings and charges performance fee
    function _harvest(address callFeeRecipient) internal whenNotPaused {
        IVelodromeGauge(gauge).getReward(address(this));
        uint256 outputBal = IERC20Upgradeable(output).balanceOf(address(this));
        if (outputBal > 0) {
            chargeFees(callFeeRecipient);
            addLiquidity();
            uint256 wantHarvested = balanceOfWant();
            deposit();

            lastHarvest = block.timestamp;
            emit StratHarvest(msg.sender, wantHarvested, balanceOf());
        }
    }

    // performance fees
    function chargeFees(address callFeeRecipient) internal {
        uint256 toNative = (IERC20Upgradeable(output).balanceOf(address(this)) * feeOnProfits) / MAX_FEE;

        ISolidlyRouter(dystRouter).swapExactTokensForTokens(
            toNative,
            0,
            outputToNativeRoute,
            address(this),
            block.timestamp
        );

        uint256 nativeBal = IERC20Upgradeable(native).balanceOf(address(this));

        uint256 callFeeAmount = (nativeBal * callFee) / MAX_FEE;
        IERC20Upgradeable(native).safeTransfer(callFeeRecipient, callFeeAmount);

        uint256 feeAmount1 = (nativeBal * fee1) / MAX_FEE;
        IERC20Upgradeable(native).safeTransfer(feeRecipient1, feeAmount1);

        uint256 feeAmount2 = (nativeBal * fee2) / MAX_FEE;
        IERC20Upgradeable(native).safeTransfer(feeRecipient2, feeAmount2);

        uint256 strategistFeeAmount = (nativeBal * strategistFee) / MAX_FEE;
        IERC20Upgradeable(native).safeTransfer(strategist, strategistFeeAmount);

        emit ChargedFees(callFeeAmount, feeAmount1, feeAmount2, strategistFeeAmount);
    }

    // Adds liquidity to AMM and gets more LP tokens.
    function addLiquidity() internal {
        uint256 outputBal = IERC20Upgradeable(output).balanceOf(address(this));
        uint256 lp0Amt = outputBal / 2;
        uint256 lp1Amt = outputBal - lp0Amt;

        if (stable) {
            uint256 lp0Decimals = 10 ** IERC20Extended(lpToken0).decimals();
            uint256 lp1Decimals = 10 ** IERC20Extended(lpToken1).decimals();
            uint256 out0 = lpToken0 != output
                ? (ISolidlyRouter(dystRouter).getAmountsOut(lp0Amt, outputToLp0Route)[outputToLp0Route.length] * 1e18) /
                    lp0Decimals
                : lp0Amt;
            uint256 out1 = lpToken1 != output
                ? (ISolidlyRouter(dystRouter).getAmountsOut(lp1Amt, outputToLp1Route)[outputToLp1Route.length] * 1e18) /
                    lp1Decimals
                : lp1Amt;
            (uint256 amountA, uint256 amountB, ) = ISolidlyRouter(dystRouter).quoteAddLiquidity(
                lpToken0,
                lpToken1,
                stable,
                factory,
                out0,
                out1
            );
            amountA = (amountA * 1e18) / lp0Decimals;
            amountB = (amountB * 1e18) / lp1Decimals;
            uint256 ratio = (((out0 * 1e18) / out1) * amountB) / amountA;
            lp0Amt = (outputBal * 1e18) / (ratio + 1e18);
            lp1Amt = outputBal - lp0Amt;
        }

        if (lpToken0 != output) {
            ISolidlyRouter(dystRouter).swapExactTokensForTokens(
                lp0Amt,
                0,
                outputToLp0Route,
                address(this),
                block.timestamp
            );
        }

        if (lpToken1 != output) {
            ISolidlyRouter(dystRouter).swapExactTokensForTokens(
                lp1Amt,
                0,
                outputToLp1Route,
                address(this),
                block.timestamp
            );
        }

        uint256 lp0Bal = IERC20Upgradeable(lpToken0).balanceOf(address(this));
        uint256 lp1Bal = IERC20Upgradeable(lpToken1).balanceOf(address(this));
        ISolidlyRouter(dystRouter).addLiquidity(
            lpToken0,
            lpToken1,
            stable,
            lp0Bal,
            lp1Bal,
            1,
            1,
            address(this),
            block.timestamp
        );
    }

    // calculate the total underlaying 'want' held by the strat.
    function balanceOf() public view returns (uint256) {
        return balanceOfWant() + balanceOfPool();
    }

    // it calculates how much 'want' this contract holds.
    function balanceOfWant() public view returns (uint256) {
        return IERC20Upgradeable(want).balanceOf(address(this));
    }

    // it calculates how much 'want' the strategy has working in the farm.
    function balanceOfPool() public view returns (uint256) {
        return IVelodromeGauge(gauge).balanceOf(address(this));
    }

    // returns rewards unharvested
    function rewardsAvailable() public view returns (uint256) {
        return IVelodromeGauge(gauge).earned(address(this));
    }

    // native reward amount for calling harvest
    function callReward() public view returns (uint256) {
        uint256 outputBal = rewardsAvailable();
        uint256 nativeOut;
        if (outputBal > 0) {
            nativeOut = ISolidlyRouter(dystRouter).getAmountsOut(outputBal, outputToNativeRoute)[
                outputToNativeRoute.length
            ];
        }

        return (((nativeOut * feeOnProfits) / MAX_FEE) * callFee) / MAX_FEE;
    }

    function setHarvestOnDeposit(bool _harvestOnDeposit) external onlyManager {
        harvestOnDeposit = _harvestOnDeposit;

        if (harvestOnDeposit) {
            setWithdrawalFee(0);
        } else {
            setWithdrawalFee(10);
        }
    }

    function setFeeOnProfits(uint256 _feeOnProfits) external onlyManager {
        feeOnProfits = _feeOnProfits;
    }

    // called as part of strat migration. Sends all the available funds back to the vault.
    function retireStrat() external {
        require(msg.sender == vault, "!vault");

        IVelodromeGauge(gauge).withdraw(balanceOfPool());

        uint256 wantBal = IERC20Upgradeable(want).balanceOf(address(this));
        IERC20Upgradeable(want).transfer(vault, wantBal);
    }

    // pauses deposits and withdraws all funds from third party systems.
    function panic() public onlyManager {
        pause();
        IVelodromeGauge(gauge).withdraw(balanceOfPool());
    }

    function pause() public onlyManager {
        _pause();

        _removeAllowances();
    }

    function unpause() external onlyManager {
        _unpause();

        _giveAllowances();

        deposit();
    }

    function _giveAllowances() internal {
        IERC20Upgradeable(want).safeApprove(gauge, type(uint).max);
        IERC20Upgradeable(output).safeApprove(dystRouter, type(uint).max);

        IERC20Upgradeable(lpToken0).safeApprove(dystRouter, 0);
        IERC20Upgradeable(lpToken0).safeApprove(dystRouter, type(uint).max);

        IERC20Upgradeable(lpToken1).safeApprove(dystRouter, 0);
        IERC20Upgradeable(lpToken1).safeApprove(dystRouter, type(uint).max);
    }

    function _removeAllowances() internal {
        IERC20Upgradeable(want).safeApprove(gauge, 0);
        IERC20Upgradeable(output).safeApprove(dystRouter, 0);

        IERC20Upgradeable(lpToken0).safeApprove(dystRouter, 0);
        IERC20Upgradeable(lpToken1).safeApprove(dystRouter, 0);
    }

    function _solidlyToRoute(ISolidlyRouter.Route[] memory _route) internal pure returns (address[] memory) {
        address[] memory route = new address[](_route.length + 1);
        route[0] = _route[0].from;
        for (uint i; i < _route.length; ++i) {
            route[i + 1] = _route[i].to;
        }
        return route;
    }

    function outputToNative() external view returns (address[] memory) {
        ISolidlyRouter.Route[] memory _route = outputToNativeRoute;
        return _solidlyToRoute(_route);
    }

    function outputToLp0() external view returns (address[] memory) {
        ISolidlyRouter.Route[] memory _route = outputToLp0Route;
        return _solidlyToRoute(_route);
    }

    function outputToLp1() external view returns (address[] memory) {
        ISolidlyRouter.Route[] memory _route = outputToLp1Route;
        return _solidlyToRoute(_route);
    }
}

